PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "categorias" (
	"id"	integer NOT NULL,
	"nombre"	varchar(255) DEFAULT NULL,
	"padre_id"	integer DEFAULT NULL,
	"orden"	integer DEFAULT '0', slug TEXT, tipo TEXT, region_origen TEXT, descripcion TEXT, descripcion_corta TEXT, anio_lanzamiento INTEGER, fabricante TEXT,
	PRIMARY KEY("id" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "juegos" (
	"id"	integer NOT NULL,
	"iframe"	varchar(500) DEFAULT NULL,
	"imagen"	varchar(500) DEFAULT NULL,
	"nombre"	varchar(255) DEFAULT NULL,
	"plataforma"	varchar(255) DEFAULT NULL,
	"url"	varchar(500) DEFAULT NULL,
	"categoria_id"	integer DEFAULT NULL, slug TEXT,
	PRIMARY KEY("id" AUTOINCREMENT),
	CONSTRAINT "FK5icn3av2dcdnefheov7refywt" FOREIGN KEY("categoria_id") REFERENCES "categorias"("id")
);
CREATE TABLE juego_detalle (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    slug TEXT NOT NULL,
    plataforma TEXT,
    nombre TEXT,
    anio INTEGER,
    genero TEXT,
    desarrollador TEXT,
    jugadores TEXT,
    estilo TEXT,
    gameplay TEXT,
    objetivo TEXT,
    descripcion_corta TEXT,
    descripcion_larga TEXT
);
DELETE FROM sqlite_sequence;
CREATE INDEX "idx_juegos_FK5icn3av2dcdnefheov7refywt" ON "juegos" (
	"categoria_id"
);
